<style>
.s606-service-page{padding:36px 0 64px;background:#faf9f6;color:#222925;min-height:50vh}.s606-service-wrap{width:min(1240px,calc(100% - 48px));margin:auto}.s606-service-heading{margin-bottom:28px}.s606-service-heading h1{font-size:clamp(28px,3vw,40px);line-height:1.3;margin:0 0 12px}.s606-service-heading p{color:#62685f;font-size:15px;line-height:1.8;margin:0;max-width:800px}.s606-service-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.s606-service-card{background:#fff;border:1px solid #e3e4dc;border-radius:6px;overflow:hidden}.s606-service-card img{display:block;width:100%;aspect-ratio:4/3;object-fit:cover}.s606-service-card>div{padding:22px}.s606-service-card h2{font-size:22px;line-height:1.4;margin:0 0 12px}.s606-service-card a{color:inherit;text-decoration:none}.s606-service-card a:hover{color:#244b40}.s606-service-card p{color:#62685f;font-size:14px;line-height:1.8;margin:0}.s606-service-breadcrumb{display:flex;gap:10px;font-size:13px;margin-bottom:24px;color:#62685f}.s606-service-detail{max-width:940px;margin:auto;padding:30px;background:#fff;border:1px solid #e3e4dc;border-radius:6px}.s606-service-cover{display:block;width:100%;max-height:440px;object-fit:cover;border-radius:4px;margin:24px 0}.s606-service-prose{font-size:15px;line-height:1.85;color:#555e54;overflow-wrap:anywhere}.s606-service-prose img{max-width:100%;height:auto}.s606-service-prose table{display:block;overflow:auto;max-width:100%}.s606-service-page a:focus-visible{outline:3px solid #879b88;outline-offset:3px}@media(max-width:900px){.s606-service-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.s606-service-wrap{width:calc(100% - 32px)}.s606-service-grid{grid-template-columns:1fr}.s606-service-detail{padding:22px}.s606-service-page{padding:24px 0 40px}}
</style>
